// test/rsa_key_parity_test.dart
//
// Parity test for lib/src/crypto/rsa_key.dart against a real RSA-2048 key
// generated by Go's crypto/rsa + crypto/x509
// (go-ipfs-reference/noise_vectors/rsa_vectors.go), self-verified in Go
// before being copied here (round-tripped through x509.ParsePKCS1PrivateKey
// and independently checked with rsa.VerifyPKCS1v15). Proves this port
// produces/accepts the exact PKCS1/PKIX DER bytes and PKCS1v1.5 signatures
// a real go-libp2p peer would.
import 'dart:typed_data';

import 'package:transpiled_libp2p/transpiled_libp2p.dart';
import 'package:test/test.dart';

Uint8List _fromHex(String hex) {
  final out = Uint8List(hex.length ~/ 2);
  for (var i = 0; i < out.length; i++) {
    out[i] = int.parse(hex.substring(i * 2, i * 2 + 2), radix: 16);
  }
  return out;
}

