const _messageHex =
    '68656c6c6f2066726f6d20646172745f69706673205253412074657374';

const _signatureHex =
    '3f2b0f207f9f7c29c858214c7f5894af78c45c6c90dfa05ff5e9ffe4e82a25a3fad295826866'
    'bc860a063088a4193216807b710da3390be5b2cedcb80a9b8474600ed10af9d3b1a7c2d8836e'
    'eca36e5a9f5a4e0e51bbc30831a21b4daa86df5c0595299acc0872bf6c35bc671067ff9ed5c8'
    '321fd815ec62e8d09ef6a5bc9116c79c03b6cf287ff3a4320e83167a9039b1a7fb700588b707'
    'f5891fc968804865af2be8aedbe4ebdf4e3b0e809a31804cd46a9160252456fbe18ae6836f2e'
    '3001d93ef8494aeda12beeb323eb8659f1cfa7842ecf00b80122e39b914f38ecbd2b559baf28'
    'ee9a7c3fac37607d131144127e11b9ad665274cc455586a4f2cb4d6b';

void main() {
  group('RSA -- real Go-generated vector', () {
    test('unmarshal PKCS1 private key, re-marshal matches byte-for-byte', () {
      final der = _fromHex(_pkcs1PrivateDerHex);
      final priv = unmarshalRsaPrivateKey(der);
      expect(priv.type, equals(KeyType.rsa));
      expect(priv.raw(), equals(der));
    });

    test('unmarshal PKIX public key, re-marshal matches byte-for-byte', () {
      final der = _fromHex(_pkixPublicDerHex);
      final pub = unmarshalRsaPublicKey(der);
      expect(pub.type, equals(KeyType.rsa));
      expect(pub.raw(), equals(der));
    });

    test("private key's derived public key matches the PKIX vector", () {
      final priv = unmarshalRsaPrivateKey(_fromHex(_pkcs1PrivateDerHex));
      expect(priv.getPublic().raw(), equals(_fromHex(_pkixPublicDerHex)));
    });

    test('verifies a real go-libp2p-style SHA256/PKCS1v1.5 signature', () async {
      final pub = unmarshalRsaPublicKey(_fromHex(_pkixPublicDerHex));
      final ok = await pub.verify(
        _fromHex(_messageHex),
        _fromHex(_signatureHex),
      );
      expect(ok, isTrue);
    });

    test('rejects a tampered signature', () async {
      final pub = unmarshalRsaPublicKey(_fromHex(_pkixPublicDerHex));
      final sig = _fromHex(_signatureHex);
      sig[0] ^= 0xff;
      final ok = await pub.verify(_fromHex(_messageHex), sig);
      expect(ok, isFalse);
    });

    test('rejects a signature over the wrong message', () async {
      final pub = unmarshalRsaPublicKey(_fromHex(_pkixPublicDerHex));
      final ok = await pub.verify(
        _fromHex('00' * 30),
        _fromHex(_signatureHex),
      );
      expect(ok, isFalse);
    });

    test("signs with Dart's own key, and Dart's own verify accepts it", () async {
      final priv = unmarshalRsaPrivateKey(_fromHex(_pkcs1PrivateDerHex));
      final sig = await priv.sign(_fromHex(_messageHex));
      // A real PKCS1v1.5 signature over a fixed key+message is
      // deterministic (no randomization in the padding scheme), so this
      // must match Go's own signature exactly.
      expect(sig, equals(_fromHex(_signatureHex)));
    });
  });

  group('RSA -- generation and round-trip', () {
    test('a freshly generated key signs and verifies its own signature', () async {
      final priv = generateRsaKeyPair(minRsaKeyBits);
      final data = Uint8List.fromList('round trip me'.codeUnits);
      final sig = await priv.sign(data);
      final ok = await (priv.getPublic() as RsaPublicKey).verify(data, sig);
      expect(ok, isTrue);
    });

    test('rejects a key smaller than minRsaKeyBits', () {
      expect(() => generateRsaKeyPair(1024), throwsArgumentError);
    });

    test('marshal -> unmarshal round-trips a freshly generated key', () async {
      final priv = generateRsaKeyPair(minRsaKeyBits);
      final reparsed = unmarshalRsaPrivateKey(priv.raw());
      expect(reparsed.raw(), equals(priv.raw()));
      expect(reparsed.getPublic().raw(), equals(priv.getPublic().raw()));

      final data = Uint8List.fromList('cross-instance check'.codeUnits);
      final sig = await priv.sign(data);
      final ok = await reparsed.getPublic().verify(data, sig);
      expect(ok, isTrue);
    });
  });
}
